    title = f"Refactor(Git): {pr_data['pr_title']}"
    body = f"### Description\n{pr_data['pr_body']}\n\n### Changes Made\n"

    for change in pr_data['changes']:
        body += f"- **{change['type']}**: {change['description']}\n"

    body += "\n### Impact\n"
    for impact in pr_data['impact']:
        body += f"- **{impact['type']}**: {impact['description']}\n"

    body += "\n### Reviewer Notes\n"
    for note in pr_data['reviewer_notes']:
        body += f"- {note}\n"

    body += "\n### References\n"
    for reference in pr_data['references']:
        body += f"- [{reference['title']}]({reference['url']})\n"

    return title, body

